import{c as i,Z as r,Q as e,j as d,m as s,o as l,av as n,n as o}from"./chunks/framework.rWdQudnF.js";const v=JSON.parse('{"title":"分页存储管理","description":"","frontmatter":{"title":"分页存储管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/分页存储管理.md","filePath":"综合知识/系统基础/操作系统/分页存储管理.md","lastUpdated":null}'),p={name:"综合知识/系统基础/操作系统/分页存储管理.md"};function c(u,t,g,h,b,m){const a=r("font");return e(),d("div",null,[t[2]||(t[2]=s(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 分页存储原理（页号/页内地址/页表/物理块号）</li><li>[x] 页面置换算法（OPT/FIFO/LRU/淘汰原则）</li><li>[x] 快表与慢表</li><li>[x] 逻辑地址→物理地址转换计算</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="分页存储原理" tabindex="-1">分页存储原理 <a class="header-anchor" href="#分页存储原理" aria-label="Permalink to &quot;分页存储原理&quot;">​</a></h3><p><strong>逻辑页分为页号和页内地址</strong>，页内地址就是物理偏移地址，页号与物理块号并非按序对应，需查询页表得知页号对应的物理块号，再用物理块号 + 偏移地址 = 物理地址。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230905232507.png" alt="分页存储"></p><ul><li>优点：利用率高，碎片小，分配及管理简单</li><li>缺点：增加了系统开销，可能产生抖动现象</li></ul><h3 id="页面置换算法" tabindex="-1">页面置换算法 <a class="header-anchor" href="#页面置换算法" aria-label="Permalink to &quot;页面置换算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>原理</th><th>特点</th></tr></thead><tbody><tr><td><strong>最优算法 (OPT)</strong></td><td>选择未来最长时间内不被访问的页面置换</td><td>理论最优，无法实现，用于基准对比</td></tr><tr><td><strong>先进先出 (FIFO)</strong></td><td>先调入内存的页先被淘汰</td><td>可能产生抖动（分配的页数越多，缺页率反而越高）</td></tr><tr><td><strong>最近最少使用 (LRU)</strong></td><td>过去最少使用的页面被淘汰</td><td>基于局部性原理，效率高，不会抖动</td></tr><tr><td><strong>淘汰原则</strong></td><td>优先淘汰最近未访问的，其次淘汰最近未被修改的</td><td>—</td></tr></tbody></table><h3 id="快表-tlb" tabindex="-1">快表（TLB） <a class="header-anchor" href="#快表-tlb" aria-label="Permalink to &quot;快表（TLB）&quot;">​</a></h3><h4 id="快表要解决什么问题" tabindex="-1">快表要解决什么问题？ <a class="header-anchor" href="#快表要解决什么问题" aria-label="Permalink to &quot;快表要解决什么问题？&quot;">​</a></h4><p>分页存储有一个性能硬伤：<strong>每次内存访问，实际要访问内存两次</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 读逻辑地址 1040 的数据：</span></span>
<span class="line"><span>  ① 先去内存查页表         → 找到页号0对应物理块号5</span></span>
<span class="line"><span>  ② 再去内存读物理地址的数据  → 取到 arr[10] 的值</span></span>
<span class="line"><span>  ↑↑ 一次读数据 = 两次内存访问，性能直接砍半</span></span></code></pre></div><p>页表存放在内存中就是<strong>慢表</strong>，每次地址翻译都多一次内存读取。</p><h4 id="快表的核心思想" tabindex="-1">快表的核心思想 <a class="header-anchor" href="#快表的核心思想" aria-label="Permalink to &quot;快表的核心思想&quot;">​</a></h4><p>快表（TLB，Translation Lookaside Buffer）是 <strong>CPU 内部的一块小型高速缓存</strong>，专门存放最近用过的页表条目。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 读逻辑地址 1040：</span></span>
<span class="line"><span>  先查快表（CPU内部，纳秒级）</span></span>
<span class="line"><span>  ├─ ✅ 命中（hit）→ 直接拿到物理块号 → 1次内存读数据</span></span>
<span class="line"><span>  └─ ❌ 未命中（miss）→ 去内存查页表（慢表）→ 拿到映射</span></span>
<span class="line"><span>                        → 写入快表（下次就快了）→ 读数据</span></span></code></pre></div><h4 id="为什么快表能生效-局部性原理" tabindex="-1">为什么快表能生效？局部性原理 <a class="header-anchor" href="#为什么快表能生效-局部性原理" aria-label="Permalink to &quot;为什么快表能生效？局部性原理&quot;">​</a></h4><ul><li><strong>时间局部性</strong>：访问了一个地址，短时间内很可能再用（如循环）</li><li><strong>空间局部性</strong>：访问了一个地址，附近地址也很快会被访问（如数组遍历）</li></ul><p>所以快表只需几十到几百个条目，就能覆盖 <strong>90%~99%</strong> 的地址翻译请求。</p><h4 id="性能对比" tabindex="-1">性能对比 <a class="header-anchor" href="#性能对比" aria-label="Permalink to &quot;性能对比&quot;">​</a></h4><table tabindex="0"><thead><tr><th>场景</th><th>访问过程</th><th>性能</th></tr></thead><tbody><tr><td><strong>无分页</strong></td><td>1 次内存</td><td>基准</td></tr><tr><td><strong>慢表（纯内存页表）</strong></td><td>2 次内存</td><td>❌ 慢一倍</td></tr><tr><td><strong>快表命中</strong></td><td>1 次快表（≈1ns）+ 1 次内存</td><td>✅ 接近无分页</td></tr><tr><td><strong>快表未命中</strong></td><td>1 次内存（页表）+ 1 次内存（数据）</td><td>❌ 退化为慢表</td></tr></tbody></table><blockquote><p>一句话：快表 = 页表的 Cache，把最近用的映射放 CPU 旁边，避免每次翻译都去内存翻表。</p></blockquote><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2>`,24)),l(a,{color:"#4bacc6"},{default:n(()=>[...t[0]||(t[0]=[o("逻辑地址转物理地址",-1)])]),_:1}),t[3]||(t[3]=s(`<p>某系统页面大小为 4K，进程页面变换表如下，逻辑地址为十六进制 1D16H，求物理地址。</p><table tabindex="0"><thead><tr><th>页号</th><th>物理块号</th></tr></thead><tbody><tr><td>0</td><td>1</td></tr><tr><td>1</td><td>3</td></tr><tr><td>2</td><td>4</td></tr><tr><td>3</td><td>6</td></tr></tbody></table><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>3D16H</strong></p><p><strong>核心原理：页内偏移不动，页号查表替换成物理块号。</strong></p><p>分页地址转换的本质是逻辑地址 → 物理地址时，<strong>页内偏移直接搬运，只有页号被替换</strong>。因为页面大小就是物理块大小，页内偏移在逻辑地址和物理地址中是相同的。</p><p><strong>步骤拆解：</strong></p><p>① 页面大小 4K = 2^12 → <strong>页内偏移占 12 位</strong>（低 12 位），剩余高位是<strong>页号</strong></p><p>② 拆分 1D16H：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1D16H = 0001  1101 0001 0110  </span></span>
<span class="line"><span>        ↑___  ↑________________  </span></span>
<span class="line"><span>       页号1    页内偏移 D16H</span></span></code></pre></div><ul><li>低 12 位 = D16H（<strong>页内偏移，直接保留</strong>）</li><li>高 4 位 = 1（逻辑页号，<strong>待映射</strong>）</li></ul><p>③ 查页表：页号 <strong>1</strong> → 物理块号 <strong>3</strong>（页号被替换）</p><p>④ 拼物理地址：物理块号 <strong>3</strong> + 页内偏移 <strong>D16H</strong> = <strong>3D16H</strong></p><p>验证公式：物理地址 = 物理块号 × 页面大小 + 页内偏移</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 × 4096 + D16H = 3 × 1000H + D16H = 3000H + D16H = 3D16H</span></span></code></pre></div></div></details><hr>`,4)),l(a,{color:"#4bacc6"},{default:n(()=>[...t[1]||(t[1]=[o("页面淘汰",-1)])]),_:1}),t[4]||(t[4]=s(`<p>某进程 4 个页面（0~3），分配 3 个存储块，访问前页面 1 不在内存。根据状态位/访问位/修改位，淘汰哪个页面代价最小？</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241021002739.png" alt="页面表"></p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>3</strong></p><p>解析：淘汰原则—<strong>优先淘汰最近未被访问的，再淘汰最近未被修改的</strong>。页 0、2、3 最近都被访问过，但只有页 3 最近未被修改，淘汰代价最小。</p></div></details><hr><p><strong>[Q48] 分页存储</strong></p><p>分页存储管理中，地址转换需要读取（ ）。</p><ul><li>A. 链表</li><li>B. 段表</li><li>C. 页表</li><li>D. 段表+页表</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：分页管理中，逻辑地址→物理地址通过查页表完成。</p></div></details><hr><p><strong>[Q56] 缺页中断</strong></p><p>以下情况会触发缺页中断（Page Fault）的是（ ）。</p><ul><li>A. 进程访问的页在物理内存中</li><li>B. 进程访问的页被标记为只读</li><li>C. 进程访问的页既不在内存也不在磁盘</li><li>D. 进程访问的页不在物理内存但存在于磁盘</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：缺页=页不在内存但在磁盘，需要调入。A 正常访问；B 是保护异常；C 是非法访问。</p></div></details><hr><p><strong>[Q63] 物理地址</strong></p><p>在页式存储管理中，以下哪种地址类型用于程序运行时在内存中的实际定位（ ）。</p><ul><li>A. 逻辑地址</li><li>B. 物理地址</li><li>C. 虚拟地址</li><li>D. 相对地址</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：物理地址=内存中实际地址；逻辑地址/虚拟地址=程序中的地址，需转换。</p></div></details><hr><p><strong>[Q105] 缺页中断类型</strong></p><p>当CPU要访问的页面不在内存中时，会引发（1）中断，系统处理该中断的过程称为（2）。</p><ul><li>A. 外部中断</li><li>B. 内部中断</li><li>C. 软中断</li><li>D. 缺页中断</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：访问的页不在内存中→缺页中断（Page Fault）。</p></div></details><hr><p><strong>[Q106] 页面置换</strong></p><p>当CPU要访问的页面不在内存中时，会引发（1）中断，系统处理该中断的过程称为（2）。</p><ul><li>A. 页面置换</li><li>B. 页面调入</li><li>C. 地址变换</li><li>D. 页面分配</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：缺页中断发生后，处理过程 = <strong>页面置换</strong>（选一页换出→调入所需页）。各选项辨析：</p><table tabindex="0"><thead><tr><th>选项</th><th>是什么</th><th>和缺页处理的关系</th></tr></thead><tbody><tr><td><strong>A. 页面置换</strong></td><td>缺页时选一页换出、调入新页的完整过程</td><td>✅ <strong>正确答案</strong>，就是中断处理过程本身</td></tr><tr><td><strong>B. 页面调入</strong></td><td>从磁盘读页面进内存</td><td>❌ 只是置换中的<strong>一个动作环节</strong>，缺了&quot;换出&quot;不完整</td></tr><tr><td><strong>C. 地址变换</strong></td><td>MMU把逻辑地址翻译成物理地址</td><td>❌ 它是每次内存访问都做的，缺页时它只是<strong>触发者</strong>，不是处理者</td></tr><tr><td><strong>D. 页面分配</strong></td><td>决定进程拥有多少个物理页框</td><td>❌ 属于内存管理<strong>策略</strong>，不参与缺页中断处理</td></tr></tbody></table><p><strong>关系图</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址变换（C）→ 发现页不在内存 → 触发缺页中断  </span></span>
<span class="line"><span>                                       ↓  </span></span>
<span class="line"><span>                                页面置换（A）  </span></span>
<span class="line"><span>                                 ├─ 选一页换出  </span></span>
<span class="line"><span>                                 └─ 页面调入（B）← 读入目标页</span></span></code></pre></div></div></details>`,28))])}const y=i(p,[["render",c]]);export{v as __pageData,y as default};
